{
  "request": "Retrieve the subscription tier and SLA commitments for the Managed Database Engine from the policy documents and database records. Specifically, query the SQLite database for customers with the Managed Database Engine subscription and their tier information, and consult the policy PDFs regarding SLA commitments and support terms. Ensure the request respects read-only constraints and preserves the specified names, date windows, and filters without calculating policy-derived results or authorizing mutations."
}

{
  "sql": "SELECT c.tier, s.plan_name, s.billing_cycle, s.monthly_rate, s.start_date, s.renewal_date, s.payment_status\nFROM customers c\nJOIN subscriptions s ON c.customer_id = s.customer_id\nWHERE s.plan_name = 'Managed Database Engine'",
  "parameters": {}
}

{
  "request": "SELECT plan_name, billing_cycle FROM subscriptions; SELECT ticket_id, severity, downtime_minutes, reported_at, resolved_at, status, sla_breached FROM incident_tickets WHERE severity = 'Severity 1';"
}
